BEGIN TRANSACTION;
CREATE TABLE "Account" (account_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES Customer(customer_id), opened_date TEXT NOT NULL, account_status TEXT NOT NULL, hardship_flag TEXT NOT NULL, risk_band TEXT NOT NULL);
CREATE TABLE "CollectionCase" (case_id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES Loan(loan_id), snapshot_id TEXT NOT NULL REFERENCES DelinquencySnapshot(snapshot_id), case_status TEXT NOT NULL, priority_score REAL NOT NULL, priority_band TEXT NOT NULL, dispute_flag TEXT NOT NULL, hardship_flag TEXT NOT NULL, next_action_date TEXT, decision_reason TEXT NOT NULL);
CREATE TABLE "ContactAttempt" (contact_attempt_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES CollectionCase(case_id), attempt_at TEXT NOT NULL, channel TEXT NOT NULL, outcome TEXT NOT NULL, agent_id TEXT NOT NULL, notes_code TEXT NOT NULL);
CREATE TABLE "ContactPreference" (preference_id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES Customer(customer_id), effective_from TEXT NOT NULL, effective_to TEXT, timezone TEXT NOT NULL, allowed_start_local TEXT NOT NULL, allowed_end_local TEXT NOT NULL, channel TEXT NOT NULL, do_not_contact TEXT NOT NULL);
CREATE TABLE "Customer" (customer_id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, created_date TEXT NOT NULL, customer_segment TEXT NOT NULL, preferred_language TEXT NOT NULL);
CREATE TABLE "DelinquencySnapshot" (snapshot_id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES Loan(loan_id), snapshot_date TEXT NOT NULL, days_past_due INTEGER NOT NULL, arrears_amount REAL NOT NULL, oldest_unpaid_due_date TEXT, snapshot_status TEXT NOT NULL);
CREATE TABLE "Installment" (installment_id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES Loan(loan_id), installment_number INTEGER NOT NULL, due_date TEXT NOT NULL, scheduled_amount REAL NOT NULL, paid_amount REAL NOT NULL, outstanding_amount REAL NOT NULL, installment_status TEXT NOT NULL, UNIQUE(loan_id, installment_number));
CREATE TABLE "Loan" (loan_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES Account(account_id), principal_amount REAL NOT NULL, annual_interest_rate REAL NOT NULL, term_months INTEGER NOT NULL, origination_date TEXT NOT NULL, loan_status TEXT NOT NULL, currency TEXT NOT NULL);
CREATE TABLE "Payment" (payment_id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES Loan(loan_id), installment_id TEXT NOT NULL REFERENCES Installment(installment_id), payment_date TEXT NOT NULL, amount REAL NOT NULL, payment_status TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE "PromiseToPay" (promise_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES CollectionCase(case_id), contact_attempt_id TEXT NOT NULL REFERENCES ContactAttempt(contact_attempt_id), promised_amount REAL NOT NULL, promise_date TEXT NOT NULL, due_date TEXT NOT NULL, promise_status TEXT NOT NULL);
COMMIT;